package com.pocketmusic.android;
import org.junit.Test;import java.util.*;import static org.junit.Assert.*;
public class DownloadPresentationTest {
 private DownloadQueue.Job job(String state,int progress){DownloadQueue.Job j=new DownloadQueue.Job("abcdefghijk","Fixture","mp3");j.state=state;j.progress=progress;return j;}
 @Test public void zeroPercentIsKnownProgressWhilePreparingIsIndeterminate(){assertFalse(DownloadPresentation.unknown(List.of(job("running",0))));assertTrue(DownloadPresentation.unknown(List.of(job("running",-1))));assertEquals(25,DownloadPresentation.progress(List.of(job("running",50),job("queued",-1))));}
 @Test public void intentionalCancellationIsHistoryRatherThanFailure(){assertEquals("finished",DownloadPresentation.group(job("cancelled",0)));assertEquals("attention",DownloadPresentation.group(job("saveFailed",100)));assertEquals("active",DownloadPresentation.group(job("queued",-1)));}
 @Test public void completedBytesAreNotReportedAsFinishedBeforeConversion(){assertEquals("Converting audio…",DownloadPresentation.state(job("running",100)));assertEquals("Saved and ready to play",DownloadPresentation.state(job("done",100)));}
 @Test public void speedAndEtaExposeOnlyTransferInformation(){DownloadQueue.Job j=job("running",42);j.speed=DownloadPresentation.speed("[download] 42% at 1.25MiB/s ETA 00:40 private metadata");j.etaSeconds=40;assertEquals("1.25MiB/s · 40s left",DownloadPresentation.transfer(j));assertEquals("",DownloadPresentation.speed("Cookie: private"));}
 @Test public void historyClearingNeverRemovesPendingWorkOrRestartsCompletedJobs(){DownloadQueue q=new DownloadQueue(2);DownloadQueue.Job active=q.enqueue("one","Active","mp3"),done=q.enqueue("two","Done","mp3"),failed=q.enqueue("three","Failed","mp3");active.state="running";done.state="done";failed.state="failed";assertFalse(q.retry(done.key));assertEquals(2,q.clearFinished().size());assertEquals(List.of(active),q.all());}
 @Test public void avatarsAcceptOnlyHttpsProfileImageHosts(){assertTrue(AccountAvatar.allowed("https://lh3.googleusercontent.com/a/profile"));assertTrue(AccountAvatar.allowed("https://yt3.ggpht.com/profile"));assertFalse(AccountAvatar.allowed("https://evil.com/avatar"));assertFalse(AccountAvatar.allowed("https://lh3.googleusercontent.com.evil.com/avatar"));assertFalse(AccountAvatar.allowed("http://lh3.googleusercontent.com/avatar"));assertFalse(AccountAvatar.allowed("https://user@lh3.googleusercontent.com/avatar"));}
}
